package com.nexodb.db;
import java.time.Instant;import java.util.List;
public final class DataLineageServiceTest {public static void main(String[] args){var relation=new DataDictionaryService.Relation("fk_pedido_cliente",List.of("cliente_id"),"public.cliente",List.of("id"),"CASCADE","RESTRICT");var table=new DataDictionaryService.Table("","public","pedido","TABLE","",List.of(),List.of(),List.of(relation),true);var graph=DataLineageService.from(new DataDictionaryService.Dictionary("ventas",Instant.now(),List.of(table),List.of()));equal(2,graph.nodes().size());equal(1,graph.edges().size());String markdown=DataLineageService.markdown(graph);if(!markdown.contains("flowchart LR")||!markdown.contains("public.pedido")||!markdown.contains("cliente_id"))throw new AssertionError(markdown);System.out.println("DataLineageServiceTest: OK (FK graph and Mermaid documentation)");}private static void equal(Object e,Object a){if(!java.util.Objects.equals(e,a))throw new AssertionError("Expected "+e+" got "+a);}}
